        }
    }

    //▼ナビゲーションバーetc.を除外してIMEの高さを計算
    val density = LocalDensity.current
    val imeInsetPx = WindowInsets.ime.exclude(WindowInsets.systemBars).getBottom(density)
    val imeInsetDp = with(density) { imeInsetPx.toDp() }

    Scaffold(
        topBar = {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(color = MaterialTheme.colorScheme.surface)
                    .windowInsetsPadding(
                        WindowInsets.safeDrawing.only(
                            WindowInsetsSides.Top + WindowInsetsSides.Horizontal
                        )
                    )
                    .padding(12.dp)
            ) {
                Text("Offset Mode")
            }
        },
        bottomBar = {
            Box(
                Modifier
                    .fillMaxWidth()
                    .navigationBarsPadding()
                    .offset(y = -imeInsetDp) // レイアウト層ではないのでinnerPaddingに影響しない
            ) {
                InputBar { text -> messages.add(text) }
            }
        }
    ) { innerPadding ->
        val listState = rememberLazyListState()

        //▼メッセージが追加/削除されたとき、最下部へ移動
        LaunchedEffect(messages.size) {
            if (messages.isNotEmpty()) {
                // 1. 最後のアイテムまで一度ジャンプし、Composeにアイテムを描画（レイアウト生成）させる
                listState.scrollToItem(messages.lastIndex)

                // 2. 描画が完了し、画面内に最後のアイテムが実際に表示されるまで待機
                snapshotFlow { listState.layoutInfo }
                    .first { info ->
                        info.visibleItemsInfo.any { it.index == messages.lastIndex }
                    }

                // 3. 画面サイズ基準でどれだけアイテムがはみ出るかの差分を計算
                // 3-1. レイアウト情報取得
                val layoutInfo = listState.layoutInfo
                // 3-2. 最後のアイテムを取得
                val lastItem = layoutInfo.visibleItemsInfo.last()
                // 3-3. アイテムの高さ - リストの表示高さ
                val offset = lastItem.size - layoutInfo.viewportSize.height

                // 4. アイテムの高さが画面に収まらない場合のみ、下端が切れないように再ジャンプで微調整
                if (offset > 0) {
                    listState.scrollToItem(messages.lastIndex, offset)
                }
            }
        }

        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .offset(y = -imeInsetDp),
            state = listState
        ) {
            items(messages) { msg ->
                MessageBubble(text = msg)
            }
        }
    }
}